/* Rekonsiliasi bank: setiap baris rekening koran harus dijelaskan oleh sesuatu
   di buku kita, dan setiap pembayaran yang kita klaim terkirim harus muncul
   di rekening koran. Dua arah, bukan satu. Kebanyakan otomasi hanya memeriksa
   arah pertama, sehingga pembayaran yang katanya lunas tapi uangnya tidak pernah
   keluar tidak pernah ketahuan.

   Urutan pemeriksaan per baris:
     1. sudah direkonsiliasi di run sebelumnya - jangan terapkan dua kali
     2. baris ganda di rekening koran yang sama
     3. biaya bank
     4. debit: cocokkan ke pembayaran terkirim lewat referensi bank
     5. kredit: nomor faktur di referensi -> faktur itu
     6. kredit: nama pengirim -> pelanggan -> kombinasi faktur terbuka yang pas jumlahnya
     7. selebihnya -> suspense */

const TOL = 1;                 /* selisih pembulatan yang ditoleransi, rupiah */
const BATAS_BIAYA = 50000;     /* debit sekecil ini dengan kata kunci biaya dianggap biaya bank */

function rp(n){ return Number(n||0).toLocaleString('id-ID'); }
function norm(s){ return String(s||'').toUpperCase().replace(/\b(PT|CV|UD|TBK)\b/g,' ')
  .replace(/[^A-Z0-9 ]/g,' ').replace(/\s+/g,' ').trim(); }
function mirip(a,b){ const A=norm(a).split(' ').filter(function(x){return x.length>2;}),
  B=norm(b).split(' ').filter(function(x){return x.length>2;});
  if(!A.length||!B.length) return 0; let s=0; for(const x of A) if(B.indexOf(x)!==-1) s++;
  return s/Math.max(A.length,B.length); }

const mutasi = $('Muat Rekening Koran').all().map(function(i){ return i.json; })
  .filter(function(r){ return r && r.line_key; })
  .sort(function(a,b){ return Number(a.line_no) - Number(b.line_no); });
const bayar = $('Muat Pembayaran Terkirim').all().map(function(i){ return i.json; }).filter(function(r){ return r && r.bank_ref; });
const faktur = $('Muat Tagihan AR').all().map(function(i){ return i.json; }).filter(function(r){ return r && r.invoice_number; });
const pelanggan = $('Muat Pelanggan AR').all().map(function(i){ return i.json; }).filter(function(r){ return r && r.customer_id; });
const logLama = $('Muat Log Pencocokan').all().map(function(i){ return i.json; }).filter(function(r){ return r && r.line_key; });

const sudah = {};
for (const l of logLama) if (l.result === 'cocok' || l.result === 'perlu_tindak') sudah[l.line_key] = l;

/* --- integritas rekening koran --- */
const awal = mutasi.length ? Number(mutasi[0].opening_balance||0) : 0;
const akhirTercatat = mutasi.length ? Number(mutasi[0].closing_balance||0) : 0;
const totKredit = mutasi.reduce(function(s,r){ return s + Number(r.credit||0); }, 0);
const totDebit = mutasi.reduce(function(s,r){ return s + Number(r.debit||0); }, 0);
const akhirHitung = awal + totKredit - totDebit;
const footingOk = Math.abs(akhirHitung - akhirTercatat) <= TOL;
const putus = [];
let saldo = awal;
for (const r of mutasi) {
  saldo = saldo + Number(r.credit||0) - Number(r.debit||0);
  if (Math.abs(saldo - Number(r.running_balance||0)) > TOL)
    putus.push({ baris:r.line_no, tercetak:Number(r.running_balance||0), seharusnya:saldo, selisih:Number(r.running_balance||0)-saldo });
}

const custById = {}; for (const c of pelanggan) custById[c.customer_id] = c;
const sisa = {};  /* sisa tagihan terbuka, dikurangi sambil jalan supaya satu faktur tidak dilunasi dua kali */
for (const f of faktur) sisa[f.invoice_number] = Math.max(0, Number(f.amount||0) - Number(f.amount_paid||0));

const keluar = [];
const terlihat = {};
const refDebit = {};

function catat(r, hasil, kodeHasil, cocokKe, diterapkan, alasan, rute, penerapan) {
  keluar.push({ json: {
    match_key: 'REC-' + String($execution.id||'manual') + '|' + r.line_key,
    line_key: r.line_key, statement_id: r.statement_id, value_date: r.value_date,
    direction: Number(r.credit||0) > 0 ? 'masuk' : 'keluar',
    amount: Number(r.credit||0) > 0 ? Number(r.credit) : Number(r.debit||0),
    counterparty: r.counterparty, reference: r.reference, line_no: r.line_no,
    result: hasil, code: kodeHasil, matched_to: cocokKe, applied_amount: diterapkan,
    reason: alasan, route_to: rute, penerapan: penerapan || [],
    execution_id: String($execution.id||'manual')
  }});
}

for (const r of mutasi) {
  const debit = Number(r.debit||0), kredit = Number(r.credit||0);
  const ref = String(r.reference||'').trim().toUpperCase();
  const kunciGanda = ref + '|' + (debit || kredit) + '|' + (debit ? 'D' : 'K');

  if (terlihat[kunciGanda]) {
    catat(r,'kritis','DUPLICATE_LINE','baris '+terlihat[kunciGanda],0,
      'Referensi '+ref+' sebesar '+rp(debit||kredit)+' sudah muncul di baris '+terlihat[kunciGanda]+' pada rekening koran yang sama. Periksa dengan bank apakah transaksinya memang terjadi dua kali.','treasury');
    continue;
  }
  terlihat[kunciGanda] = r.line_no;
  /* Baris yang dilewati TETAP harus meninggalkan jejaknya untuk pemeriksaan lain.
     Versi pertama melewatinya sebelum mencatat apa pun, dan run kedua pun
     (a) menerima debit ganda sebagai pembayaran sah, karena baris aslinya tak
     pernah tercatat "terlihat", dan (b) menuduh pembayaran 480 juta tidak pernah
     keluar, karena referensinya tak pernah tercatat sudah didebet. */
  if (sudah[r.line_key]) {
    if (debit > 0) refDebit[ref] = true;
    catat(r,'lewati','ALREADY_RECONCILED',String(sudah[r.line_key].matched_to||''),0,
      'Baris ini sudah direkonsiliasi pada run '+String(sudah[r.line_key].execution_id||'sebelumnya')+'. Menerapkannya lagi akan melunasi tagihan dua kali.','-');
    continue;
  }


  if (debit > 0) {
    const desk = String(r.description||'').toUpperCase();
    if (debit < BATAS_BIAYA && /BIAYA|ADMIN|FEE|CHARGE|PROVISI/.test(desk)) {
      catat(r,'cocok','BANK_FEE','akun biaya bank',debit,'Biaya bank '+rp(debit)+' ('+r.description+'). Dibukukan ke biaya administrasi bank.','accounting');
      continue;
    }
    const p = bayar.filter(function(x){ return String(x.bank_ref).toUpperCase() === ref; })[0];
    if (p) {
      refDebit[ref] = true;
      const bersih = Number(p.amount||0) - Number(p.discount_taken||0);
      if (String(p.status) === 'rejected') {
        catat(r,'kritis','REJECTED_BUT_DEBITED',p.vendor+' '+p.invoice_number,0,
          'Catatan pembayaran menyatakan transfer '+ref+' DITOLAK bank ('+String(p.reject_reason||'tanpa alasan')+'), tapi rekening koran menunjukkan '+rp(debit)+' benar-benar keluar. Uangnya keluar dan tidak tercatat terbayar - vendor bisa dibayar lagi.','treasury');
      } else if (Math.abs(bersih - debit) > TOL) {
        catat(r,'kritis','AMOUNT_DIFFERS',p.vendor+' '+p.invoice_number,0,
          'Debit '+rp(debit)+' tapi pembayaran '+ref+' tercatat '+rp(bersih)+'. Selisih '+rp(debit-bersih)+'.','treasury');
      } else {
        catat(r,'cocok','MATCH_PAYMENT',p.vendor+' '+p.invoice_number,debit,
          'Debit '+rp(debit)+' cocok dengan pembayaran '+ref+' ke '+p.vendor+'.','accounting');
      }
      continue;
    }
    catat(r,'kritis','UNEXPLAINED_DEBIT','',0,
      'Uang keluar '+rp(debit)+' ke '+r.counterparty+' tanpa pembayaran apa pun di buku kita. Ini yang paling mendesak di seluruh rekonsiliasi.','treasury');
    continue;
  }

  /* --- kredit --- */
  const noFak = (ref.match(/INV-\d+/) || String(r.description||'').toUpperCase().match(/INV-\d+/) || [])[0];
  if (noFak) {
    const f = faktur.filter(function(x){ return x.invoice_number === noFak; })[0];
    if (!f) {
      catat(r,'suspense','UNKNOWN_INVOICE',noFak,0,'Referensi menyebut '+noFak+' tapi faktur itu tidak ada di buku AR.','ar_clerk');
      continue;
    }
    const cust = custById[f.customer_id];
    const terbuka = sisa[noFak];
    if (String(f.status) === 'disputed') {
      catat(r,'perlu_tindak','DISPUTED_PAID',noFak,kredit,
        (cust?cust.name:f.customer_id)+' membayar '+rp(kredit)+' untuk '+noFak+' yang masih DISENGKETAKAN ('+String(f.dispute_reason||'')+'). Dana diterapkan, tapi sengketanya harus ditutup - kalau nota kredit tetap diterbitkan, pelanggan jadi kelebihan bayar.','ar_manager',
        [{ invoice_number:noFak, customer_id:f.customer_id, apply:kredit, amount_paid_baru:Number(f.amount_paid||0)+kredit }]);
      sisa[noFak] = Math.max(0, terbuka - kredit);
      continue;
    }
    if (Math.abs(kredit - terbuka) <= TOL) {
      catat(r,'cocok','MATCH_EXACT',noFak,kredit,'Pas melunasi '+noFak+' ('+rp(kredit)+').','accounting',
        [{ invoice_number:noFak, customer_id:f.customer_id, apply:kredit, amount_paid_baru:Number(f.amount_paid||0)+kredit }]);
      sisa[noFak] = 0;
    } else if (kredit < terbuka) {
      catat(r,'perlu_tindak','PARTIAL',noFak,kredit,
        'Dibayar '+rp(kredit)+' dari sisa '+rp(terbuka)+'. Masih kurang '+rp(terbuka-kredit)+' - tagihan tetap terbuka dan penagihan AR akan mengejar sisanya.','ar_clerk',
        [{ invoice_number:noFak, customer_id:f.customer_id, apply:kredit, amount_paid_baru:Number(f.amount_paid||0)+kredit }]);
      sisa[noFak] = terbuka - kredit;
    } else {
      catat(r,'perlu_tindak','OVERPAYMENT',noFak,terbuka,
        'Dibayar '+rp(kredit)+' untuk sisa '+rp(terbuka)+'. Kelebihan '+rp(kredit-terbuka)+' dicatat sebagai kredit pelanggan, bukan dianggap pendapatan.','ar_clerk',
        [{ invoice_number:noFak, customer_id:f.customer_id, apply:terbuka, amount_paid_baru:Number(f.amount_paid||0)+terbuka }]);
      sisa[noFak] = 0;
    }
    continue;
  }

  /* tanpa nomor faktur: cari pelanggan dari nama pengirim, lalu kombinasi faktur yang pas */
  const cust = pelanggan.filter(function(c){ return mirip(c.name, r.counterparty) >= 0.6; })[0];
  if (cust) {
    const buka = faktur.filter(function(f){ return f.customer_id===cust.customer_id && sisa[f.invoice_number]>0 && String(f.status)!=='disputed'; })
      .sort(function(a,b){ return String(a.due_date).localeCompare(String(b.due_date)); });
    let kombinasi = null;
    const n = Math.min(buka.length, 12);
    for (let m = 1; m < (1<<n) && !kombinasi; m++) {
      let s = 0; const pilih = [];
      for (let i = 0; i < n; i++) if (m & (1<<i)) { s += sisa[buka[i].invoice_number]; pilih.push(buka[i]); }
      if (Math.abs(s - kredit) <= TOL) kombinasi = pilih;
    }
    if (kombinasi) {
      catat(r,'cocok', kombinasi.length>1 ? 'MATCH_COMBINED' : 'MATCH_EXACT',
        kombinasi.map(function(f){return f.invoice_number;}).join(' + '), kredit,
        cust.name+' membayar '+rp(kredit)+' tanpa menyebut nomor faktur. Jumlahnya pas dengan '+kombinasi.length+' tagihan terbuka: '
        + kombinasi.map(function(f){ return f.invoice_number+' ('+rp(sisa[f.invoice_number])+')'; }).join(' + ')+'.','accounting',
        kombinasi.map(function(f){ return { invoice_number:f.invoice_number, customer_id:f.customer_id,
          apply:sisa[f.invoice_number], amount_paid_baru:Number(f.amount_paid||0)+sisa[f.invoice_number] }; }));
      for (const f of kombinasi) sisa[f.invoice_number] = 0;
      continue;
    }
    catat(r,'suspense','NO_MATCHING_COMBINATION',cust.name,0,
      cust.name+' membayar '+rp(kredit)+', tapi tidak ada kombinasi tagihan terbukanya yang pas dengan jumlah itu. Ditaruh di suspense sampai pelanggan menyebutkan fakturnya.','ar_clerk');
    continue;
  }
  catat(r,'suspense','UNKNOWN_PAYER','',0,
    'Uang masuk '+rp(kredit)+' dari '+r.counterparty+' (ref '+r.reference+'). Pengirimnya tidak cocok dengan pelanggan mana pun. Disimpan di suspense - bukan dianggap pendapatan - sampai ada yang mengenali.','ar_clerk');
}

/* --- arah kebalikan: yang katanya terbayar tapi tidak pernah keluar --- */
/* Hanya pembayaran yang lunas DI DALAM rentang tanggal rekening koran ini.
   Tanpa batas ini, pembayaran bulan lalu tampak "hilang" dari rekening koran
   bulan ini - kebisingan palsu yang mengajari orang mengabaikan bagian kritis. */
const tglMin = mutasi.reduce(function(a,r){ return (!a || String(r.value_date) < a) ? String(r.value_date) : a; }, '');
const tglMax = mutasi.reduce(function(a,r){ return (!a || String(r.value_date) > a) ? String(r.value_date) : a; }, '');
for (const p of bayar) {
  if (String(p.status) !== 'settled') continue;
  const tglLunas = String(p.settled_on||'').slice(0,10);
  if (!tglLunas || tglLunas < tglMin || tglLunas > tglMax) continue;
  if (refDebit[String(p.bank_ref).toUpperCase()]) continue;
  const bersih = Number(p.amount||0) - Number(p.discount_taken||0);
  keluar.push({ json: {
    match_key: 'REC-' + String($execution.id||'manual') + '|MISSING|' + p.bank_ref,
    line_key: 'MISSING|' + p.bank_ref, statement_id: mutasi.length ? mutasi[0].statement_id : '',
    value_date: String(p.settled_on||''), direction: 'keluar', amount: bersih,
    counterparty: p.vendor, reference: p.bank_ref, line_no: 0,
    result: 'kritis', code: 'MISSING_DEBIT', matched_to: p.vendor+' '+p.invoice_number, applied_amount: 0,
    reason: 'Pembayaran '+p.bank_ref+' ke '+p.vendor+' sebesar '+rp(bersih)+' tercatat LUNAS pada '+String(p.settled_on||'-')
      +', tapi tidak ada debit apa pun di rekening koran. Vendor mungkin belum menerima uangnya, sementara buku kita sudah menganggapnya terbayar.',
    route_to: 'treasury', penerapan: [], execution_id: String($execution.id||'manual')
  }});
}

/* integritas ikut di setiap baris supaya laporan bisa membacanya dari mana pun */
const integ = { saldo_awal:awal, total_kredit:totKredit, total_debit:totDebit, saldo_akhir_hitung:akhirHitung,
  saldo_akhir_tercatat:akhirTercatat, footing_ok:footingOk, baris_saldo_putus:putus };
for (const k of keluar) k.json.integritas = integ;
return keluar;

