/* Satu baris rekening koran bisa melunasi beberapa faktur sekaligus, jadi
   penerapan kas dipecah per faktur sebelum ditulis ke AR. */
const out = [];
/* Dibaca dari Kumpulkan Hasil, BUKAN $input: masukan node ini adalah keluaran
   Tulis Log Pencocokan, yang hanya mengembalikan kolom yang dipetakan. Larik
   penerapan tidak ikut, sehingga node ini mengeluarkan 0 item dan tidak satu
   rupiah pun sampai ke AR - dengan run yang tetap hijau. */
for (const it of $('Kumpulkan Hasil').all()) {
  const r = it.json || {};
  for (const p of (r.penerapan || [])) {
    out.push({ json: { invoice_number:p.invoice_number, amount_paid:p.amount_paid_baru,
      dari_baris:r.line_key, kode:r.code, diterapkan:p.apply } });
  }
}
return out;

function rp(n){ return Number(n||0).toLocaleString('id-ID'); }
const semua = $('Kumpulkan Hasil').all().map(function(i){ return i.json; });
let tertulis=[]; try{ tertulis=$('Tulis Log Pencocokan').all().map(function(i){return i.json;}).filter(function(r){return r&&r.id!==undefined&&r.id!==null;}); }catch(e){}
let arDiperbarui=[]; try{ arDiperbarui=$('Terapkan ke Tagihan AR').all().map(function(i){return i.json;}).filter(function(r){return r&&r.id!==undefined&&r.id!==null;}); }catch(e){}
const integ = (semua[0]||{}).integritas || {};
function g(h){ return semua.filter(function(r){ return r.result===h; }); }
function jum(a){ return a.reduce(function(s,r){ return s+Number(r.amount||0); },0); }
const cocok=g('cocok'), tindak=g('perlu_tindak'), kritis=g('kritis'), suspense=g('suspense'), lewat=g('lewati');
return [{ json: {
  statement_id: (semua[0]||{}).statement_id || '-',
  tanggal: new Date().toISOString().slice(0,10),
  total: semua.length,
  cocok: cocok.length, nilai_cocok: jum(cocok),
  perlu_tindak: tindak.length, nilai_perlu_tindak: jum(tindak),
  kritis: kritis.length, nilai_kritis: jum(kritis),
  suspense: suspense.length, nilai_suspense: jum(suspense),
  dilewati: lewat.length,
  log_tertulis: tertulis.length, log_gagal: semua.length - tertulis.length,
  tagihan_ar_diperbarui: arDiperbarui.length,
  footing_ok: integ.footing_ok === true,
  saldo_awal: Number(integ.saldo_awal||0), total_kredit: Number(integ.total_kredit||0),
  total_debit: Number(integ.total_debit||0), saldo_akhir_hitung: Number(integ.saldo_akhir_hitung||0),
  saldo_akhir_tercatat: Number(integ.saldo_akhir_tercatat||0),
  saldo_putus: integ.baris_saldo_putus || [],
  daftar_kritis: kritis.map(function(r){ return { kode:r.code, baris:r.line_no, nilai:r.amount, ke:r.counterparty, alasan:r.reason }; }),
  daftar_tindak: tindak.map(function(r){ return { kode:r.code, faktur:r.matched_to, nilai:r.amount, alasan:r.reason }; }),
  daftar_suspense: suspense.map(function(r){ return { kode:r.code, nilai:r.amount, dari:r.counterparty, ref:r.reference, alasan:r.reason }; }),
  daftar_cocok: cocok.map(function(r){ return { kode:r.code, nilai:r.amount, ke:r.matched_to }; })
}}];

const b = (($input.first().json||{}).body) || $input.first().json || {};
const d = Array.isArray(b.resolutions) ? b.resolutions : [];
if (!d.length) return [{ json:{ _kosong:true } }];
return d.map(function(x){ return { json:{
  line_key:String(x.line_key||''), invoice_number:String(x.invoice_number||''),
  amount:Number(x.amount||0), resolved_by:String(x.resolved_by||''), note:String(x.note||'')
}};});

/* Penugasan suspense tetap diperiksa, bukan diterapkan buta. Orang yang
   menyelesaikan suspense bisa salah pilih faktur, dan kas yang diterapkan ke
   faktur yang salah membuat DUA pelanggan salah sekaligus. */
function rp(n){ return Number(n||0).toLocaleString('id-ID'); }
const tagihan = $('Muat Tagihan untuk Suspense').all().map(function(i){return i.json;}).filter(function(r){return r&&r.invoice_number;});
return $('Baca Penyelesaian').all().map(function(i){
  const r = i.json || {};
  const f = tagihan.filter(function(t){ return t.invoice_number===r.invoice_number; })[0];
  const sisa = f ? Math.max(0, Number(f.amount||0)-Number(f.amount_paid||0)) : 0;
  let ok=false, alasan='';
  if (!r.resolved_by) alasan='Tidak ada nama penyelesai. Setiap penerapan kas harus bisa ditelusuri ke seseorang.';
  else if (!f) alasan='Faktur '+r.invoice_number+' tidak ada.';
  else if (String(f.status)==='disputed') alasan=r.invoice_number+' sedang disengketakan; selesaikan sengketanya dulu.';
  else if (r.amount > sisa + 1) alasan='Jumlah '+rp(r.amount)+' melebihi sisa tagihan '+rp(sisa)+' pada '+r.invoice_number+'.';
  else { ok=true; alasan='Diterapkan '+rp(r.amount)+' ke '+r.invoice_number+' oleh '+r.resolved_by+'. '+r.note; }
  return { json: Object.assign({}, r, { sah:ok, alasan:alasan,
    amount_paid_baru: f ? Number(f.amount_paid||0)+r.amount : 0, customer_id: f ? f.customer_id : '' }) };
});

const s = $('Kumpulkan Penugasan').all().map(function(i){return i.json;});
let t=[]; try{ t=$('Terapkan Suspense ke AR').all().map(function(i){return i.json;}).filter(function(r){return r&&r.id!==undefined&&r.id!==null;}); }catch(e){}
const sah=s.filter(function(r){return r.status_akhir==='diterapkan';}), tolak=s.filter(function(r){return r.status_akhir!=='diterapkan';});
return [{ json:{ diproses:s.length, diterapkan:sah.length, ditolak:tolak.length, ar_diperbarui:t.length,
  daftar_tolak: tolak.map(function(r){ return { faktur:r.invoice_number, alasan:r.alasan }; }) }}];
